if(!type){
	if(!vip){
result='https://app.jjwxc.org/androidapi/chapterContent?novelId='+novelid+'&chapterId='+chapterid
}else{result='https://app.jjwxc.org/androidapi/chapterContent?novelId='+novelid+'&versionCode=191&token='+cookie.getKey('https://m.jjwxc.net','sid')+'&chapterId='+chapterid}
}else{result=''}

searchUrl:
@js:
url='https://app.jjwxc.org/androidapi/search?versionCode=282&keyword=';
if(/^#.*#$/.test(key)){
	result=url+String(key).replace(/^#(.*)#$/,'$1')+'&type=2&page={{page}}'
	}else if(/^主角#.*#$/.test(key)){
		result=url+String(key).replace(/^主角#(.*)#$/,'$1')+'&type=4&page={{page}}'
		}else if(/^配角#.*#$/.test(key)){
			result=url+String(key).replace(/^配角#(.*)#$/,'$1')+'&type=5&page={{page}}'
			}else if(/^其他#.*#$/.test(key)){
				result=url+String(key).replace(/^其他#(.*)#$/,'$1')+'&type=6&page={{page}}'
				}else if(/^ID#.*#$/.test(key)){
					result=url+String(key).replace(/^ID#(.*)#$/,'$1')+'&type=7&page={{page}}'
					}else{result=url+'&keyword={{key}}&page={{page}}'}

